mapper.select:
/* 공통팀 유민상 isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.selectCtgrySeCdList 공통팀 유민상 */
SELECT A.CMMNS_CD_ID , A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM , A.UP_CMMNS_CD_VALUE , B.UNT_TASKWK_SE_CD FROM SAC100 A, SAC110 B WHERE 1=1 AND A.CMMNS_CD_ID = 'UNITY_BBSCTT_CTGRYB_SE_CD' AND A.CMMNS_CD_VALUE = B.CMMNS_CD_VALUE(+) AND A.UP_CMMNS_CD_VALUE = #{UNITY_BBSCTT_TYPE_SE_CD} AND A.USE_YN = 'Y'
AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
ORDER BY SRTNG_SQNCE

/* isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.selectSysCtgtybInstList 응용3팀 이상훈 */
SELECT A.CMMNS_CD_ID , A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM , A.UP_CMMNS_CD_VALUE FROM SAC100 A WHERE 1=1 AND A.CMMNS_CD_ID = 'UNITY_BBSCTT_CTGRYB_SE_CD' AND A.UP_CMMNS_CD_VALUE = #{UNITY_BBSCTT_TYPE_SE_CD} AND A.USE_YN = 'Y'
ORDER BY SRTNG_SQNCE

/* 공통팀 유민상 isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.selectCtgrySeCdList 공통팀 유민상 */
SELECT A.CMMNS_CD_ID , A.CMMNS_CD_VALUE , A.CMMNS_CD_VALUE_NM , A.UP_CMMNS_CD_VALUE FROM SAC100 A WHERE 1=1 AND A.CMMNS_CD_ID = 'UNITY_BBSCTT_CTGRYB_SE_CD' AND A.UP_CMMNS_CD_VALUE = #{UNITY_BBSCTT_TYPE_SE_CD} AND A.USE_YN = 'Y'
ORDER BY SRTNG_SQNCE

/* 공통팀 유민상 isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.getTotalCount 공통팀 유민상 */
SELECT COUNT(*) FROM SBA130 A LEFT JOIN ( SELECT SBA131.* , ROW_NUMBER() OVER(PARTITION BY UNITY_BBSCTT_ESNTAL_NO ORDER BY FRST_REG_DT DESC) AS ROW_NUMBER FROM SBA131 WHERE DEL_YN != 'Y' ) B ON B.ROW_NUMBER = 1 AND B.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO WHERE 1=1 AND NVL(A.DEL_YN, 'N') != 'Y' AND A.UNITY_BBSCTT_TYPE_SE_CD = #{UNITY_BBSCTT_TYPE_SE_CD}
AND #{UNT_TASKWK_SE_CD} IN ( SELECT B.UNT_TASKWK_SE_CD FROM SBA132 B WHERE B.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO )
AND #{strUNT_TASKWK_SE_CD} IN ( SELECT B.UNT_TASKWK_SE_CD FROM SBA132 B WHERE B.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO )
AND A.UNITY_BBSCTT_CTGRYB_SE_CD = #{UNITY_BBSCTT_CTGRYB_SE_CD}
AND A.UNITY_BBSCTT_CTGRYB_SE_CD IN ( SELECT C.CMMNS_CD_VALUE FROM SAC100 C, SAC110 D WHERE 1=1 AND C.CMMNS_CD_ID = 'UNITY_BBSCTT_CTGRYB_SE_CD' AND C.CMMNS_CD_VALUE = D.CMMNS_CD_VALUE(+) AND C.USE_YN = 'Y' AND C.UP_CMMNS_CD_VALUE = #{UNITY_BBSCTT_TYPE_SE_CD}
AND D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
)
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') < A.PSTG_BGNG_YMD)
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.PSTG_BGNG_YMD AND A.PSTG_END_YMD)
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') > A.PSTG_END_YMD)
AND (UNITY_BBSCTT_TTL_NM LIKE '%' || #{SEARCH_DATA} || '%' OR UNITY_BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%')
AND UNITY_BBSCTT_TTL_NM LIKE '%'|| #{SEARCH_DATA} || '%'
AND UNITY_BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%'
AND C##RG.SA_FN_GET_NAME(A.FRST_RGTR_ID) = ENC_B64(#{SEARCH_DATA})
AND UNITY_BBSCTT_TYPE_SN = #{SEARCH_DATA}
AND ENC_B64(#{SEARCH_DATA}) IN (SELECT T3.FLNM_ENCPT FROM SBA131 T1 JOIN SAA200 T2 ON T2.USER_ID = T1.FRST_RGTR_ID JOIN SCA100 T3 ON T3.ENFSN_NO = T2.ENFSN_NO WHERE T1.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO)
AND (A.FRST_REG_DT BETWEEN #{START_DATE} AND #{END_DATE})
AND A.PSTG_BGNG_YMD <= #{PR_END_DATE} AND A.PSTG_END_YMD >= #{PR_START_DATE}
AND A.OGDP_INST_NO IN (SELECT INST_NO FROM SAA000 WHERE INST_NO = #{USER_INST_NO} OR UP_INST_NO = #{USER_INST_NO})
AND A.OGDP_INST_NO = #{USER_INST_NO}
AND CLLR_REG_YN = #{CLLR_REG_YN}
AND
B.UNITY_BBSCTT_ESNTAL_NO IS NULL
B.TASKWK_PRCS_SE_CD = #{arr}
AND B.TASKWK_TASKFO_SE_CD = #{TASKWK_TASKFO_SE_CD}
AND A.FRST_RGTR_ID = #{USER_ID}
AND SYSDATE - A.FRST_REG_DT > 1
ORDER BY A.FRST_REG_DT DESC

/* 공통팀 유민상 isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.selectItgCmnBrdImprtnList 공통팀 유민상 */
WITH TEMP AS ( SELECT A.UNITY_BBSCTT_ESNTAL_NO , A.UNITY_BBSCTT_TYPE_SE_CD , A.UNITY_BBSCTT_TYPE_SN , A.UNITY_BBSCTT_CTGRYB_SE_CD , A.IMPRTN_NTC_YN AS HIGH_LIGHT_YN , A.OGDP_INST_NO , A.OGDP_DEPT_CD , A.PSTG_BGNG_YMD , A.PSTG_END_YMD , A.UNITY_BBSCTT_TTL_NM , A.UNITY_BBSCTT_CN , A.RLS_YN , A.RDCNT_NOCS , A.ATFINO , (SELECT COUNT(MNG_SN) FROM SAB821 WHERE ATFINO = A.ATFINO AND FILE_STTS_SE_CD != 'D' AND ATCMFL_CL_NM = '0') AS ATFI_CNT , DEC_B64(SA_FN_GET_NAME(A.FRST_RGTR_ID)) AS FRST_RGTR_NM , A.FRST_RGTR_ID , TO_CHAR(TO_DATE(A.PSTG_BGNG_YMD,'YYYYMMDD'), 'YYYY-MM-DD') || ' ~ ' || TO_CHAR(TO_DATE(A.PSTG_END_YMD,'YYYYMMDD'), 'YYYY-MM-DD') AS PSTG_BGNG_END_YMD , TO_CHAR(A.FRST_REG_DT, 'YYYYMMDD') AS FRST_REG_DT , CASE WHEN TRUNC(SYSDATE - A.FRST_REG_DT) > 3 THEN 'N' ELSE 'Y' END AS NEW_BBSCTT , (SELECT COUNT(*) FROM SBA131 C WHERE NVL(C.DEL_YN, 'N') != 'Y' AND C.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO) AS CMNT_CNT FROM SBA130 A WHERE 1=1 AND NVL(A.DEL_YN, 'N') != 'Y' AND A.UNITY_BBSCTT_TYPE_SE_CD = #{UNITY_BBSCTT_TYPE_SE_CD} AND #{UNT_TASKWK_SE_CD} IN ( SELECT B.UNT_TASKWK_SE_CD FROM SBA132 B WHERE B.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO )
AND A.UNITY_BBSCTT_CTGRYB_SE_CD = #{UNITY_BBSCTT_CTGRYB_SE_CD}
AND A.UNITY_BBSCTT_CTGRYB_SE_CD IN ( SELECT C.CMMNS_CD_VALUE FROM SAC100 C, SAC110 D WHERE 1=1 AND C.CMMNS_CD_ID = 'UNITY_BBSCTT_CTGRYB_SE_CD' AND C.CMMNS_CD_VALUE = D.CMMNS_CD_VALUE(+) AND C.USE_YN = 'Y' AND C.UP_CMMNS_CD_VALUE = #{UNITY_BBSCTT_TYPE_SE_CD} AND D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} )
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') < A.PSTG_BGNG_YMD)
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.PSTG_BGNG_YMD AND A.PSTG_END_YMD)
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') > A.PSTG_END_YMD)
AND A.OGDP_INST_NO = #{OGDP_INST_NO}
AND EXISTS (SELECT 1 FROM SAA000 B WHERE A.OGDP_INST_NO = B.INST_NO AND B.INST_NM LIKE '%'||#{OGDP_INST_NM}||'%')
AND A.OGDP_DEPT_CD = #{OGDP_DEPT_CD}
/*2023.08.30 운영팀 정현진 학교밖 요청사항으로 작성일 대신 게시기간으로 정렬조건 변경*/ ORDER BY A.IMPRTN_NTC_YN DESC,A.PSTG_BGNG_YMD DESC /*ORDER BY A.IMPRTN_NTC_YN DESC,A.FRST_REG_DT DESC*/ )
SELECT T1.* , (SELECT B.INST_NM FROM SAA000 B WHERE T1.OGDP_INST_NO = B.INST_NO) OGDP_INST_NM FROM TEMP T1 WHERE 1=1
AND (T1.UNITY_BBSCTT_TTL_NM LIKE '%' || #{SEARCH_DATA} || '%' OR T1.UNITY_BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%')
AND T1.UNITY_BBSCTT_TTL_NM LIKE '%'|| #{SEARCH_DATA} || '%'
AND T1.UNITY_BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%'
AND C##RG.SA_FN_GET_NAME(T1.FRST_RGTR_ID) = ENC_B64(#{SEARCH_DATA})
AND UNITY_BBSCTT_TYPE_SN = #{SEARCH_DATA}
AND (T1.FRST_REG_DT BETWEEN #{START_DATE} AND #{END_DATE})
OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

/* 공통팀 유민상 isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.selectItgCmnBrdList 공통팀 유민상 */
SELECT A.UNITY_BBSCTT_ESNTAL_NO , A.UNITY_BBSCTT_TYPE_SE_CD , A.UNITY_BBSCTT_TYPE_SN , A.UNITY_BBSCTT_CTGRYB_SE_CD , A.IMPRTN_NTC_YN , A.OGDP_INST_NO , A.OGDP_DEPT_CD
, SUBSTR(A.PSTG_BGNG_YMD, 1, 4) || '.' || SUBSTR(A.PSTG_BGNG_YMD, 5, 2) || '.' || SUBSTR(A.PSTG_BGNG_YMD, 7, 2) AS PSTG_BGNG_YMD
, A.PSTG_BGNG_YMD
, A.PSTG_END_YMD , A.UNITY_BBSCTT_TTL_NM , A.UNITY_BBSCTT_CN , A.RLS_YN , A.RDCNT_NOCS , A.ATFINO , (SELECT COUNT(MNG_SN) FROM SAB821 WHERE ATFINO = A.ATFINO AND FILE_STTS_SE_CD != 'D' AND ATCMFL_CL_NM = '0') AS ATFI_CNT , DEC_B64(SA_FN_GET_NAME(A.FRST_RGTR_ID)) AS FRST_RGTR_NM , A.FRST_RGTR_ID , TO_CHAR(TO_DATE(A.PSTG_BGNG_YMD,'YYYYMMDD'), 'YYYY-MM-DD') || ' ~ ' || TO_CHAR(TO_DATE(A.PSTG_END_YMD,'YYYYMMDD'), 'YYYY-MM-DD') AS PSTG_BGNG_END_YMD , TO_CHAR(A.FRST_REG_DT, 'YYYYMMDD') AS FRST_REG_DT , CASE WHEN TRUNC(SYSDATE - A.FRST_REG_DT) > 3 THEN 'N' ELSE 'Y' END AS NEW_BBSCTT , SUBSTR(B.RGN_CD, 1, 2) AS CTPV_SE_CD , B.RGN_CD , B.INST_NM AS OGDP_INST_NM FROM SBA130 A, SAA000 B WHERE 1=1 AND NVL(A.DEL_YN, 'N') != 'Y' AND A.UNITY_BBSCTT_TYPE_SE_CD = #{UNITY_BBSCTT_TYPE_SE_CD} AND A.OGDP_INST_NO = B.INST_NO
AND A.PSTG_BGNG_YMD <= TO_CHAR(SYSDATE, 'YYYYMMDD')
AND #{UNT_TASKWK_SE_CD} IN ( SELECT B.UNT_TASKWK_SE_CD FROM SBA132 B WHERE B.UNITY_BBSCTT_ESNTAL_NO = A.UNITY_BBSCTT_ESNTAL_NO )
AND A.UNITY_BBSCTT_CTGRYB_SE_CD = #{UNITY_BBSCTT_CTGRYB_SE_CD}
AND A.UNITY_BBSCTT_CTGRYB_SE_CD IN ( SELECT C.CMMNS_CD_VALUE FROM SAC100 C, SAC110 D WHERE 1=1 AND C.CMMNS_CD_ID = 'UNITY_BBSCTT_CTGRYB_SE_CD' AND C.CMMNS_CD_VALUE = D.CMMNS_CD_VALUE(+) AND C.USE_YN = 'Y' AND C.UP_CMMNS_CD_VALUE = #{UNITY_BBSCTT_TYPE_SE_CD} AND D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} )
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') < A.PSTG_BGNG_YMD)
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN A.PSTG_BGNG_YMD AND A.PSTG_END_YMD)
AND (TO_CHAR(SYSDATE, 'YYYYMMDD') > A.PSTG_END_YMD)
AND SUBSTR(B.RGN_CD, 1, 2) = #{CTPV_SE_CD}
AND B.RGN_CD = #{SGG_CD}
AND A.OGDP_INST_NO = #{OGDP_INST_NO}
AND B.INST_NM LIKE '%' || #{OGDP_INST_NM} || '%'
AND A.OGDP_DEPT_CD = #{OGDP_DEPT_CD}
AND (UNITY_BBSCTT_TTL_NM LIKE '%' || #{SEARCH_DATA} || '%' OR UNITY_BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%')
AND UNITY_BBSCTT_TTL_NM LIKE '%'|| #{SEARCH_DATA} || '%'
AND UNITY_BBSCTT_CN LIKE '%' || #{SEARCH_DATA} || '%'
AND C##RG.SA_FN_GET_NAME(FRST_RGTR_ID) = #{SEARCH_DATA}
AND UNITY_BBSCTT_TYPE_SN = #{SEARCH_DATA}
AND (TO_CHAR(A.FRST_REG_DT,'YYYYMMDD') BETWEEN #{START_DATE} AND #{END_DATE})
AND A.PSTG_BGNG_YMD <= #{PR_END_DATE} AND A.PSTG_END_YMD >= #{PR_START_DATE}
AND A.OGDP_INST_NO IN (SELECT INST_NO FROM SAA000 WHERE INST_NO = #{USER_INST_NO} OR UP_INST_NO = #{USER_INST_NO})
AND A.OGDP_INST_NO = #{USER_INST_NO}
ORDER BY A.FRST_REG_DT DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

mapper.update:
/* isry.itgcms.itgBrd.mapper.itgBrdCmnMapper."deleteItgNtcBrd" 공통팀 유민상
*/
UPDATE SBA130 SET
DEL_YN = 'Y'
, LAST_MDFCN_DT = SYSDATE
, LAST_MDFR_ID = #{LAST_MDFR_ID}
WHERE 1=1
AND UNITY_BBSCTT_ESNTAL_NO = #{UNITY_BBSCTT_ESNTAL_NO__origin}

mapper.insert:


			  SELECT SBA130_SQ01.NEXTVAL AS UNITY_BBSCTT_ESNTAL_NO
                FROM DUAL



		/* 공통팀 유민상
		isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.insertItgBrdCmnList 공통팀 유민상
