		, PSTG_END_YMD
		, UNITY_BBSCTT_TTL_NM

			, UNITY_BBSCTT_CN


			, ATFINO


			, CTTPC_ENCPT


			, RLS_YN


            , CLLR_REG_YN


            , ACTVT_NOCS

		, RDCNT_NOCS
		, CNTN_IP_ADDR
		, DEL_YN
		, FRST_RGTR_ID
		, FRST_REG_DT
