/*  isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.updateRdcntItgBrdDtlList 공통팀 유민상 */
UPDATE SBA130 SET

    RDCNT_NOCS = NVL(TO_NUMBER(RDCNT_NOCS), 0) +1

WHERE 1=1
AND UNITY_BBSCTT_ESNTAL_NO = #{UNITY_BBSCTT_ESNTAL_NO}

		/* isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.updateItgBrdCmnList 공통팀
		유민상 */
		UPDATE SBA130 SET
		LAST_MDFCN_DT = SYSDATE
		, LAST_MDFR_ID = #{LAST_MDFR_ID}

			, UNITY_BBSCTT_CTGRYB_SE_CD = #{UNITY_BBSCTT_CTGRYB_SE_CD}


            , CD_PRVSON_ETC_NM = #{CD_PRVSON_ETC_NM}


			, IMPRTN_NTC_YN = #{IMPRTN_NTC_YN}


			, PSTG_BGNG_YMD = #{PSTG_BGNG_YMD}


			, PSTG_END_YMD = #{PSTG_END_YMD}


			, UNITY_BBSCTT_TTL_NM = #{UNITY_BBSCTT_TTL_NM}


			, UNITY_BBSCTT_CN = #{UNITY_BBSCTT_CN}


			, ATFINO = #{ATFINO}


			, CTTPC_ENCPT = ENC_B64(#{CTTPC_ENCPT})


			, RLS_YN = #{RLS_YN}


            , CLLR_REG_YN = #{CLLR_REG_YN}


            , ACTVT_NOCS = #{ACTVT_NOCS}

		WHERE 1=1
		AND UNITY_BBSCTT_ESNTAL_NO =
		#{UNITY_BBSCTT_ESNTAL_NO__origin}

