/*
isry.itgcms.itgBrd.mapper.itgBrdCmnMapper.deleteItgBrdCmnTaskSysSeCdList
공통팀 유민상 */
DELETE FROM SBA132
WHERE 1=1
AND UNITY_BBSCTT_ESNTAL_NO = #{UNITY_BBSCTT_ESNTAL_NO}
